def maxSumKNonAdjacent(nums, k):
    NEG = -10 ** 18
    prev2 = [0] + [NEG] * k      # f[i-2]
    prev1 = [0] + [NEG] * k      # f[i-1]
    for idx, x in enumerate(nums):
        cur = prev1[:]
        for j in range(1, min(k, (idx + 2) // 2) + 1):
            v = prev2[j - 1] + x
            if v > cur[j]:
                cur[j] = v
        prev2, prev1 = prev1, cur
    return prev1[k]
